from dataclasses import dataclass
from datetime import date, datetime, timedelta


@dataclass
class Subscription:
    plan: str
    started_on: date
    renews_on: date

    @classmethod
    def start(cls, plan: str, today: date | None = None) -> "Subscription":
        today = today or date.today()
        return cls(plan=plan, started_on=today, renews_on=today + timedelta(days=30))

    @property
    def banner(self) -> str:
        return f"Renews on {self.renews_on:%B} {self.renews_on.day}, {self.renews_on.year}"

    def is_due(self) -> bool:
        return datetime.now().date() >= self.renews_on

import secrets
import string

ALPHABET = string.ascii_uppercase + string.digits


def generate_coupon_code(prefix: str, length: int = 6) -> str:
